def build(cells, path):
    nb = {
        "cells": [
            {"cell_type": t, "metadata": {}, "source": src.splitlines(keepends=True),
             **({"outputs": [], "execution_count": None} if t == "code" else {})}
            for t, src in cells
        ],
        "metadata": {
            "kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"},
            "language_info": {"name": "python", "version": "3.10"},
        },
        "nbformat": 4,
        "nbformat_minor": 4,
    }
    with open(path, "w") as f:
        json.dump(nb, f, indent=1)
    print("wrote", path, f"({len(cells)} cells)")

build(NB1_CELLS, OUT / "nb1_features.ipynb")
build(NB2_CELLS, OUT / "nb2_train.ipynb")
build(NB3_CELLS, OUT / "nb3_submit.ipynb")
